const DIMS=[['concept','Concept depth',25],['reasoning','Reasoning chain',25],['computation','Computation',20],['integration','Topic integration',20],['representation','Representation',10]],BCOLORS={Easy:'#70c9ae',Moderate:'#e0b769',Tough:'#dd8b98'};
const difficultyState={easy:35,tough:65,unit:'questions',excludeMTA:true,confidence:'all',minN:3,topicSort:'hard',compareA:2021,compareB:2026};
let difficultyQuestionBand='all';
function toughBand(score){return score<difficultyState.easy?'Easy':score<difficultyState.tough?'Moderate':'Tough'}
function toughRows(){return scope().filter(q=>q.toughness&&(!difficultyState.excludeMTA||q.scoring_status!=='marks_to_all')&&(difficultyState.confidence!=='high'||q.toughness.confidence==='high'))}
function toughStats(a){const n=a.length,marks=sum(a.map(q=>q.marks)),scores=a.map(q=>q.toughness.score);return {n,marks,avg:n?mean(scores):null,weighted:marks?sum(a.map(q=>q.toughness.score*q.marks))/marks:null,median:n?quant(scores,.5):null,sd:n>1?sd(scores):null,iqr:n?[quant(scores,.25),quant(scores,.75)]:null,bands:Object.fromEntries(['Easy','Moderate','Tough'].map(b=>[b,{n:a.filter(q=>toughBand(q.toughness.score)===b).length,marks:sum(a.filter(q=>toughBand(q.toughness.score)===b).map(q=>q.marks))}]))}}
function toughPill(score){const b=toughBand(score);return `<span class="difficulty-pill" style="--band:${BCOLORS[b]}">${F(score,2)} <small>${b.toUpperCase()}</small></span>`}
function toughYearChart(a){const ys=scopeYears(),by=ys.map(y=>({y,s:toughStats(a.filter(q=>q.year===y))})),unit=difficultyState.unit,max=Math.max(1,...by.map(x=>unit==='questions'?x.s.n:x.s.marks)),w=690,step=590/Math.max(1,ys.length),bw=Math.min(42,step*.53);return `<div class="panel-content"><div class="legend difficulty-legend">${['Easy','Moderate','Tough'].map(b=>`<span><i style="background:${BCOLORS[b]}"></i>${b.toUpperCase()}</span>`).join('')}<span>${unit.toUpperCase()} / PAPER</span></div><svg class="chart" viewBox="0 0 ${w} 288" role="img" aria-label="Easy moderate and tough ${unit} for each year">${[0,.5,1].map(v=>`<line class="gridline" x1="40" x2="655" y1="${232-v*185}" y2="${232-v*185}"/><text x="10" y="${235-v*185}">${F(v*max,0)}</text>`).join('')}${by.map((x,i)=>{let pos=232;return ['Easy','Moderate','Tough'].map(b=>{let v=x.s.bands[b][unit==='questions'?'n':'marks'],h=v/max*185;pos-=h;return `<g data-diff-drill="${x.y}" data-band="${b}" tabindex="0" role="button" aria-label="Open ${x.y} ${b} questions"><rect x="${45+i*step+step/2-bw/2}" y="${pos}" width="${bw}" height="${Math.max(0,h-.7)}" rx="2" fill="${BCOLORS[b]}"><title>${x.y} / ${b}: ${v} ${unit}; mean score ${F(x.s.avg)}</title></rect>${h>17?`<text x="${45+i*step+step/2}" y="${pos+h/2+3}" text-anchor="middle" style="fill:#182128;font-size:9px">${v}</text>`:''}</g>`}).join('')+`<text x="${45+i*step+step/2}" y="256" text-anchor="middle">${x.y}</text><text x="${45+i*step+step/2}" y="275" text-anchor="middle" style="fill:#b3c6df">μ ${F(x.s.avg)}</text>`}).join('')}</svg></div>`}
function toughYearTable(a){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Year</th><th>Easy</th><th>Moderate</th><th>Tough</th><th>Easy marks</th><th>Tough marks</th><th>Mean / median</th><th>Score IQR</th></tr></thead><tbody>${scopeYears().map(y=>{let s=toughStats(a.filter(q=>q.year===y));return `<tr data-diff-year="${y}"><td>${y} <small>${s.n} scored records</small></td>${['Easy','Moderate','Tough'].map(b=>`<td class="numeric" style="color:${BCOLORS[b]}">${s.bands[b].n}</td>`).join('')}<td class="numeric">${s.bands.Easy.marks}</td><td class="numeric">${s.bands.Tough.marks}</td><td class="numeric">${F(s.avg)} / ${F(s.median)}</td><td class="numeric">${s.iqr?s.iqr.map(v=>F(v)).join('–'):'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function toughTopicGroups(a){const keys=[...new Set(a.map(q=>q.subject+'\u0000'+q.topic_family))];return keys.map(key=>{let [subject,topic]=key.split('\u0000'),items=a.filter(q=>q.subject===subject&&q.topic_family===topic),s=toughStats(items);return {subject,topic,items,...s,share:s.bands.Tough.n/s.n,volatility:s.sd||0}})}
function toughTopics(a){let rows=toughTopicGroups(a).filter(g=>g.n>=difficultyState.minN).sort((a,b)=>difficultyState.topicSort==='easy'?a.avg-b.avg:difficultyState.topicSort==='marks'?b.bands.Easy.marks-a.bands.Easy.marks:difficultyState.topicSort==='volatile'?b.volatility-a.volatility:b.avg-a.avg);return `<div class="table-scroll" style="max-height:570px"><table class="data-table"><thead><tr><th>Topic family / subject</th><th>n</th><th>Mean score</th><th>Easy / Mod / Tough</th><th>Tough %</th><th>Easy marks</th><th>SD</th><th>Range</th></tr></thead><tbody>${rows.map(g=>`<tr data-diff-topic="${E(g.topic)}" data-subject="${E(g.subject)}"><td>${E(g.topic)}<small>${E(g.subject)}</small></td><td class="numeric">${g.n}</td><td>${toughPill(g.avg)}</td><td><div class="band-strip">${['Easy','Moderate','Tough'].map(b=>`<span style="width:${g.bands[b].n/g.n*100}%;background:${BCOLORS[b]}" title="${b}: ${g.bands[b].n}"></span>`).join('')}</div><small>${g.bands.Easy.n} / ${g.bands.Moderate.n} / ${g.bands.Tough.n}</small></td><td class="numeric">${F(g.share*100)}%</td><td class="numeric">${g.bands.Easy.marks}</td><td class="numeric">${F(g.sd)}</td><td class="numeric">${F(Math.min(...g.items.map(q=>q.toughness.score)))}–${F(Math.max(...g.items.map(q=>q.toughness.score)))}</td></tr>`).join('')||'<tr><td colspan="8">No topic reaches the minimum sample. Lower the minimum n or widen scope.</td></tr>'}</tbody></table></div>`}
function toughHeat(a){const ys=scopeYears(),subjects=R.subjects.filter(s=>a.some(q=>q.subject===s));return `<div class="table-scroll panel-content"><table class="heat"><thead><tr><th>MEAN SCORE / 100</th>${ys.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${subjects.map(s=>`<tr><td>${E(short(s))}</td>${ys.map(y=>{let items=a.filter(q=>q.year===y&&q.subject===s),m=items.length?mean(items.map(q=>q.toughness.score)):null,col=m===null?'#1c2633':m<difficultyState.easy?'rgba(91,175,151,.35)':m<difficultyState.tough?`rgba(201,159,82,${.15+m/150})`:`rgba(195,106,125,${.15+m/150})`;return `<td data-diff-heat-year="${y}" data-subject="${E(s)}" style="background:${col}" title="${E(s)} ${y}: ${items.length} items">${F(m,1)}<small class="heat-n">n=${items.length}</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function toughHistogram(a){let bins=Array(20).fill(0);a.forEach(q=>bins[Math.min(19,Math.floor(q.toughness.score/5))]++);let max=Math.max(...bins,1);return `<div class="panel-content"><svg class="chart" viewBox="0 0 480 205" role="img" aria-label="Toughness score histogram, neutral bins independent of band cutoffs">${[0,.5,1].map(v=>`<line class="gridline" x1="30" x2="457" y1="${165-v*130}" y2="${165-v*130}"/><text x="3" y="${168-v*130}">${F(v*max,0)}</text>`).join('')}${bins.map((n,i)=>`<rect x="${35+i*20.5}" y="${165-n/max*130}" width="18" height="${n/max*130}" rx="2" fill="#7baff5"><title>${i*5}–${i*5+5}: ${n} questions</title></rect>`).join('')}${[0,25,50,75,100].map(v=>`<text x="${35+v/100*410}" y="185" text-anchor="middle">${v}</text>`).join('')}</svg><div class="difficulty-percentiles">${[.1,.25,.5,.75,.9].map(p=>`<span>P${p*100}<b>${a.length?F(quant(a.map(q=>q.toughness.score),p)):'—'}</b></span>`).join('')}</div></div>`}
function toughOpportunity(a){let gs=toughTopicGroups(a).filter(g=>g.n>=difficultyState.minN),max=Math.max(1,...gs.map(g=>g.marks));return `<div class="panel-content"><svg class="chart" viewBox="0 0 550 245" role="img" aria-label="Topic marks versus average toughness scatter plot">${[0,.5,1].map(v=>`<line class="gridline" x1="45" x2="515" y1="${200-v*155}" y2="${200-v*155}"/><text x="8" y="${203-v*155}">${F(v*max,0)}</text>`).join('')}<line x1="45" x2="515" y1="200" y2="200" stroke="#40516a"/>${gs.map(g=>`<circle data-diff-topic="${E(g.topic)}" data-subject="${E(g.subject)}" cx="${45+g.avg/100*460}" cy="${200-g.marks/max*155}" r="${4+Math.sqrt(g.n)*1.2}" fill="${BCOLORS[toughBand(g.avg)]}" fill-opacity=".65" stroke="#101923"><title>${E(g.topic)} / ${E(g.subject)}: ${F(g.avg)} toughness, ${g.marks} marks, n=${g.n}</title></circle>`).join('')}${[0,25,50,75,100].map(v=>`<text x="${45+v/100*460}" y="220" text-anchor="middle">${v}</text>`).join('')}<text x="515" y="241" text-anchor="end">TOUGHNESS →</text><text x="45" y="23">CUMULATIVE MARKS ↑</text></svg></div>`}
function toughCompare(a){const opts=y=>scopeYears().map(x=>`<option ${x===y?'selected':''}>${x}</option>`).join('');let ys=scopeYears(),ya=ys.includes(difficultyState.compareA)?difficultyState.compareA:ys[0],yb=ys.includes(difficultyState.compareB)?difficultyState.compareB:ys.at(-1),aa=a.filter(q=>q.year===ya),bb=a.filter(q=>q.year===yb),sa=toughStats(aa),sb=toughStats(bb),delta=aa.length&&bb.length?sum(aa.flatMap(x=>bb.map(y=>Math.sign(y.toughness.score-x.toughness.score))))/(aa.length*bb.length):null;return `<div class="compare-tools"><label>BASE <select id="compareA" aria-label="Base comparison year">${opts(ya)}</select></label><span>→</span><label>COMPARE <select id="compareB" aria-label="Comparison year">${opts(yb)}</select></label></div><div class="stat-grid">${[['Δ mean score',sa.n&&sb.n?F(sb.avg-sa.avg):'—',`${yb} minus ${ya}`],['Δ tough share',sa.n&&sb.n?F((sb.bands.Tough.n/sb.n-sa.bands.Tough.n/sa.n)*100)+' pp':'—','Percentage-point change'],["Cliff’s delta",F(delta,3),'Positive = comparison scores higher'],['Samples',sa.n+' / '+sb.n,'Question counts in each paper']].map(([l,v,n])=>`<div class="stat-cell"><label>${l}</label><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><div class="panel-content compare-dimensions">${DIMS.map(([key,label])=>{let x=aa.length?mean(aa.map(q=>q.toughness.dimensions[key])):null,y=bb.length?mean(bb.map(q=>q.toughness.dimensions[key])):null;return `<div><span>${label}</span><b>${F(x)} → ${F(y)}</b><div class="dimension-pair"><i style="width:${(x||0)/4*100}%;background:#6e92c0"></i><i style="width:${(y||0)/4*100}%;background:#e0b769"></i></div></div>`}).join('')}</div>`}
function toughQuestions(a){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Question</th><th>Topic</th><th>Toughness</th><th>C / R / A / I / V</th><th>Why this score?</th></tr></thead><tbody>${[...a].sort((a,b)=>b.toughness.score-a.toughness.score).slice(0,12).map(q=>`<tr data-question="${E(q.id)}"><td class="numeric">${q.id.replace('GATE-EC-','')} ↗<small>${q.marks} MARKS / ${q.type}</small></td><td>${E(q.topic_family)}<small>${E(q.subject)}</small></td><td>${toughPill(q.toughness.score)}</td><td class="numeric">${DIMS.map(([k])=>q.toughness.dimensions[k]).join(' / ')}<small>${E(q.toughness.confidence)} CONFIDENCE</small></td><td class="difficulty-reason">${E(q.toughness.rationale)}</td></tr>`).join('')}</tbody></table></div>`}
function difficulty(){const a=toughRows(),s=toughStats(a),scopeN=scope().length,excluded=scopeN-a.length,ratio=s.marks?s.bands.Tough.marks/s.marks*100:null;return `<div class="difficulty-intro"><div><span class="mini-tag amber">QUESTION-LEVEL TOUGHNESS / 100</span><p>Compare the challenge of every year, subject and topic. Open a question to see its scored reasoning.</p></div><a href="toughness-audit.csv" class="link" download>ALL 520 SCORES ↧</a></div><div class="difficulty-jumps"><button data-diff-jump="difficulty-year">Year profile ↓</button><button data-diff-jump="difficulty-topics">Topic rankings ↓</button><button data-diff-jump="difficulty-map">Topic × year ↓</button><button data-diff-jump="difficulty-questions">Question scores ↓</button></div><div class="difficulty-controls"><label>Easy below <input id="easyCut" type="number" min="1" max="98" value="${difficultyState.easy}" aria-label="Easy score threshold"></label><label>Tough from <input id="toughCut" type="number" min="2" max="100" value="${difficultyState.tough}" aria-label="Tough score threshold"></label><button id="applyDifficultyBands" class="button">Apply bands</button><label class="checkbox-label"><input id="excludeMTA" type="checkbox" ${difficultyState.excludeMTA?'checked':''}> Exclude MTA / free marks</label><label>Confidence <select id="difficultyConfidence" aria-label="Difficulty confidence"><option value="all">All assessed</option><option value="high" ${difficultyState.confidence==='high'?'selected':''}>High only</option></select></label><button class="link" id="difficultyReset">RESET RUBRIC BANDS ↺</button></div>`+metricCards([['Mean toughness',F(s.avg),`${s.n} assessed questions · ${excluded} excluded`,'/ 100'],['Easy / moderate / tough',`${s.bands.Easy.n} <span style="color:#536579">/</span> ${s.bands.Moderate.n} <span style="color:#536579">/</span> ${s.bands.Tough.n}`,'Question counts at current thresholds'],['Easy-mark pool',s.bands.Easy.marks,`${s.marks} total marks in active difficulty cohort`,'marks'],['Tough-mark share',(ratio===null?'—':F(ratio)+'%'),`${s.bands.Tough.marks} marks on tough-rated questions`]])+`<div id="difficulty-year" class="grid-two difficulty-grid">${panel('01','How tough was each year?','Click a stack to inspect its questions. μ = mean structural toughness.',toughYearChart(a),`<div class="tabs"><button data-diff-unit="questions" class="${difficultyState.unit==='questions'?'active':''}">QUESTIONS</button><button data-diff-unit="marks" class="${difficultyState.unit==='marks'?'active':''}">MARKS</button></div>`,`Easy < ${difficultyState.easy} · Moderate ${difficultyState.easy}–<${difficultyState.tough} · Tough ≥ ${difficultyState.tough}. Bands are editable.`)}${panel('02','The challenge distribution','A score for every reviewed question; no bell curve assumed.',toughHistogram(a),'','Structural estimates from a prepared-candidate rubric, not measured success rates.')}</div>`+panel('03','Every year, broken down','Counts and marks refer to the same selected cohort.',toughYearTable(a),'','MTA tasks are structurally scored but contribute free marks in the actual exam. Default excludes them.')+toughTopicHighlights(a)+`<div id="difficulty-topics" class="difficulty-section-head"><div><h2>Which topics are tough? Which are easy?</h2><p>Rank by mean challenge, easy marks or variation. Sample size stays visible.</p></div><div class="compare-tools"><select id="topicDifficultySort" aria-label="Topic difficulty sort">${[['hard','Toughest first'],['easy','Easiest first'],['marks','Most easy marks'],['volatile','Most variable']].map(([k,l])=>`<option value="${k}" ${k===difficultyState.topicSort?'selected':''}>${l}</option>`).join('')}</select><label>Min n <input id="topicMinN" type="number" min="1" max="100" value="${difficultyState.minN}" aria-label="Minimum topic sample"></label></div></div>`+panel('04','Topic difficulty ledger','Click a topic for its underlying questions and score rationale.',toughTopics(a),'','Topic means do not make every question in that topic easy or tough. Inspect the mix and range.')+`<div class="grid-two difficulty-grid" style="margin-top:18px">${panel('05','Marks versus challenge','Large bubbles contain more questions. High marks / lower score is upper-left.',toughOpportunity(a),'','Historical opportunity map; it does not predict future weight or your personal success.')}${panel('06','Compare two papers','Same rubric and active subject scope across both years.',toughCompare(a),'','Cliff’s delta is descriptive. Questions are clustered in papers; no independent-item significance test is claimed.')}</div>`+panel('07','Where the challenge moved','Subject × year mean toughness, with question counts.',toughHeat(a),'','Cell color uses current cutoffs. A cell mean is not a calibrated pass probability.')+`<div style="height:18px"></div>`+'<div id="difficulty-questions"></div>'+panel('08','Inspect the highest-challenge questions','Component ratings and task-specific rationale; open any row for full evidence.',toughQuestions(a),'','C concept · R reasoning · A computation · I integration · V representation. Components are rated 0–4.')+toughTopicHeatPanel(a)+toughRubric()}
function toughRubric(){return `<details class="panel toughness-method" style="margin-top:18px"><summary>HOW TOUGHNESS IS ASSIGNED · rubric, thresholds and uncertainty</summary><div class="method-text"><p>Each of the 520 questions was individually assessed from its reviewed content and source notes for a prepared GATE EC candidate. The score is a transparent content-based estimate. It is separate from empirical item difficulty and can disagree with actual student performance.</p><p class="mono">T = 25C/4 + 25R/4 + 20A/4 + 20I/4 + 10V/4</p><div class="definitions">${DIMS.map(([k,l,w])=>`<div><b>${l} · ${w}%</b><p>${window.TOUGHNESS.rubric.anchors[k].map((s,i)=>`${i}: ${E(s)}`).join('<br>')}</p></div>`).join('')}</div><p>Marks, question format, text length and legacy IRT numbers do not add toughness points. Each dimension is an AI judgment; confidence and uncertainty are retained per question. The 35/65 band cutoffs are design choices and can be changed above. Topic rankings with small n are unstable. Scores are not calibrated to response rates or solving time.</p></div></details>`}
function toughInspector(q){if(!q.toughness)return '';let t=q.toughness;return `<div class="detail-card toughness-detail"><h3>TOUGHNESS / EXPLAIN THIS QUESTION</h3><div class="tough-score-big">${toughPill(t.score)}<span> / 100</span></div><p>${E(t.rationale)}</p>${DIMS.map(([k,l,w])=>`<div class="score-component"><span>${l}</span><div><i style="width:${t.dimensions[k]/4*100}%"></i></div><b>${t.dimensions[k]}/4</b><small>${F(t.dimensions[k]*w/4,2)} pts</small></div>`).join('')}<p>Estimated solution actions: ${t.cognitive_steps_estimate} · Confidence: ${E(t.confidence)}<br>${E(t.uncertainty_note||'No extra uncertainty note.')}</p><p class="sub">Prepared-candidate structural estimate. Reviewable judgment, not an observed student difficulty measure.</p></div>`}
function exportDifficulty(){const rows=toughRows(),data={version:R.version,cohort:{from:$('#from').value,to:$('#to').value,subject:$('#subject').value,review:$('#quality').value,topicDetail:topicField,...difficultyState},summary:toughStats(rows),years:scopeYears().map(year=>({year,...toughStats(rows.filter(q=>q.year===year))})),topics:toughTopicGroups(rows).map(({items,...s})=>s),questions:rows.map(q=>({id:q.id,year:q.year,subject:q.subject,topic_family:q.topic_family,score:q.toughness.score,band:toughBand(q.toughness.score),dimensions:q.toughness.dimensions,rationale:q.toughness.rationale,confidence:q.toughness.confidence}))};download('gate-toughness-analysis.json',JSON.stringify(data,null,2),'application/json');toast('Exported scores, year breakdowns, topic statistics and active thresholds.')}
document.addEventListener('change',e=>{const id=e.target.id;let handled=true;if(id==='easyCut'||id==='toughCut'){return}else if(id==='excludeMTA')difficultyState.excludeMTA=e.target.checked;else if(id==='difficultyConfidence')difficultyState.confidence=e.target.value;else if(id==='topicDifficultySort')difficultyState.topicSort=e.target.value;else if(id==='topicMinN')difficultyState.minN=Math.max(1,Math.min(100,+e.target.value||3));else if(id==='compareA')difficultyState.compareA=+e.target.value;else if(id==='compareB')difficultyState.compareB=+e.target.value;else if(id==='questionToughnessBand'){difficultyQuestionBand=e.target.value;page=0}else handled=false;if(handled)render()});
document.addEventListener('click',e=>{let u=e.target.closest('[data-diff-unit]'),y=e.target.closest('[data-diff-year]'),drill=e.target.closest('[data-diff-drill]'),topic=e.target.closest('[data-diff-topic]'),heat=e.target.closest('[data-diff-heat-year]');if(u){difficultyState.unit=u.dataset.diffUnit;render()}if(y){$('#from').value=$('#to').value=y.dataset.diffYear;render()}if(heat){$('#from').value=$('#to').value=heat.dataset.diffHeatYear;$('#subject').value=heat.dataset.subject;render()}if(drill){$('#from').value=$('#to').value=drill.dataset.diffDrill;difficultyQuestionBand=drill.dataset.band;query='';verdict='all';page=0;location.hash='questions';if(view==='questions')render()}if(topic){query=topic.dataset.diffTopic;$('#subject').value=topic.dataset.subject;difficultyQuestionBand='all';verdict='all';page=0;location.hash='questions';if(view==='questions')render()}if(e.target.id==='difficultyReset'){difficultyState.easy=35;difficultyState.tough=65;difficultyState.confidence='all';difficultyState.excludeMTA=true;difficultyState.minN=3;render()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-diff-drill]')){e.preventDefault();e.target.click()}});

document.addEventListener('click',e=>{if(e.target.id==='applyDifficultyBands'){let easy=Number($('#easyCut').value),tough=Number($('#toughCut').value);if(!Number.isFinite(easy)||!Number.isFinite(tough)||easy<1||tough>100||easy>=tough){toast('Use 1 ≤ easy cutoff < tough cutoff ≤ 100.');return}difficultyState.easy=easy;difficultyState.tough=tough;render()}});

document.addEventListener('click',e=>{let b=e.target.closest('[data-diff-jump]');if(b)document.getElementById(b.dataset.diffJump)?.scrollIntoView({behavior:'smooth',block:'start'})});
